mapper.select:
SELECT da.id,da.ip,da.`host`,da.`port`,da.rounds,da.`timestamp` ,GROUP_CONCAT(concat(da.method,'',da.path)) path ,GROUP_CONCAT(distinct da.component) component ,ii.country ii_country,ii.provider ii_provider,ii.city ii_city ,ii.asnumber ii_asnumber,ii.isp ii_isp, ii.province ii_province,ii.zipcode ii_zipcode,ii.district ii_district, v.`vulnerability` v_vulnerability FROM (SELECT da.* FROM doh_attribute da
da.ip = #{params.ip}
AND da.`port` = #{params.port}
) da LEFT JOIN ip_information ii ON da.ip=ii.ip LEFT JOIN `vulnerability` v ON v.`component` = da.`component`
GROUP BY da.ip,da.port,da.host,da.rounds order by da.`timestamp` desc LIMIT #{params.n},#{params.m}

SELECT
COUNT(distinct da.ip) count,ii.`province`
FROM (SELECT DISTINCT ip from doh_attribute


        ip = #{params.ip}


        and port = #{params.port}


) da
JOIN `ip_information` ii
ON da.ip = ii.ip AND ii.province IS NOT NULL AND ii.province !=''
GROUP BY ii.province

SELECT
COUNT(ip_attr.ip) count,ii.`provider`
from
(SELECT DISTINCT ip from doh_attribute


        ip = #{params.ip}


        and port = #{params.port}


) ip_attr
JOIN `ip_information` ii on ip_attr.ip = ii.ip AND ii.provider IS NOT NULL AND ii.provider !=''

GROUP BY ii.provider

SELECT provider,SUM(COUNT) count FROM( SELECT ii.`provider`,COUNT(da.ip) COUNT,da.ip FROM (SELECT id, ip from doh_attribute
ip = #{params.ip}
) da JOIN `ip_information` ii ON da.ip = ii.ip GROUP BY ii.provider
UNION ALL SELECT ii.`provider`,COUNT(distinct s.ip) COUNT,s.ip FROM `scan_result` s JOIN `ip_information` ii ON s.ip = ii.ip GROUP BY ii.provider ) a1
a1.ip = #{params.ip}
GROUP BY a1.provider HAVING provider IS NOT NULL AND provider !=''

SELECT
da.component,COUNT(distinct da.ip) count
FROM (SELECT DISTINCT ip,component from doh_attribute
where
component IS NOT NULL AND component !=''

    and ip = #{params.ip}


    and port = #{params.port}

) da
GROUP BY da.component


SELECT count(1) count from (
SELECT distinct da.ip from `doh_attribute` da


        da.ip = #{params.ip}


        and da.port = #{params.port}


) a

SELECT COUNT(1) count FROM (
SELECT ip,PORT,HOST,rounds
FROM `doh_attribute` da


        da.ip = #{params.ip}


        and da.port = #{params.port}


GROUP BY ip,PORT,HOST,rounds
) a1

SELECT vulnerability,COUNT(distinct ip) count FROM (
SELECT da.ip,da.port,da.host,da.`component`
,v.`vulnerability`
FROM `doh_attribute` da
JOIN `vulnerability` v ON v.`component` = da.`component` AND vulnerability IS NOT NULL AND vulnerability != ''


        da.ip = #{params.ip}


        and da.port = #{params.port}


) a1

GROUP BY a1.vulnerability

SELECT vulnerability,COUNT(distinct ip) count FROM ( SELECT da.ip ,v.`vulnerability` FROM `doh_attribute` da JOIN `vulnerability` v ON v.`component` = da.`component` where vulnerability IS NOT NULL AND vulnerability !=''
and ip = #{params.ip}
UNION ALL
SELECT s.ip ,v.`vulnerability` FROM `scan_result` s JOIN `vulnerability` v ON v.`component` = s.`component` where vulnerability IS NOT NULL AND vulnerability !=''
and ip = #{params.ip}
) a1
GROUP BY a1.vulnerability

SELECT COUNT(ip) count,`port` FROM
(SELECT DISTINCT ip,port from doh_attribute
where `port` is not null AND `port` != ''

    and ip = #{params.ip}


    and port = #{params.port}

) da
GROUP BY port

select da.rep_body, da.rep_header
from doh_attribute da
where da.ip = #{ip}
  AND da.port = #{port}
  AND da.host = #{host}
  AND da.rounds = #{rounds}

SELECT da.*, GROUP_CONCAT(concat(da.method, '', da.path)) path, ii.country ii_country, ii.provider ii_provider, ii.city ii_city, ii.asnumber ii_asnumber, ii.isp ii_isp, ii.province ii_province, ii.zipcode ii_zipcode, ii.district ii_district, v.`vulnerability` v_vulnerability from (select da.ip from (select count(1), d.ip from doh_attribute d
d.ip = #{params.ip}
and d.`port` = #{params.port}
group by d.ip) da JOIN scan_result s on da.ip = s.ip) dip join doh_attribute da on da.ip = dip.ip left join ip_information ii on ii.ip = dip.ip left join vulnerability v on v.component = da.component
group by da.ip, da.host, da.`port`, da.rounds order by da.`timestamp` desc LIMIT #{params.offset},#{params.limit}

select count(1) from (SELECT da.id, da.ip, da.host, da.`port`, da.rounds from (select da.ip from (select count(1), d.ip from doh_attribute d
d.ip = #{params.ip}
and d.`port` = #{params.port}
group by d.ip) da JOIN scan_result s on da.ip = s.ip ) dip join doh_attribute da on da.ip = dip.ip group by da.ip, da.host, da.`port`, da.rounds) total

select count(distinct dh.ip) count ,dh.`port`
from (select distinct ip,`port` from doh_attribute


        ip = #{params.ip}


        and port = #{params.port}


) dh
join scan_result sc on sc.ip = dh.ip
group by dh.`port`
having dh.`port` is not null AND dh.`port` != ''

UNION ALL

select count(distinct sc.ip) count,'53' as `port`
from (select distinct ip,`port` from doh_attribute da


        da.ip = #{params.ip}


) dh
join scan_result sc on sc.ip = dh.ip

SELECT ii.`province`,COUNT(distinct s.ip) COUNT FROM ( select sc.id,sc.ip from `scan_result` sc
sc.ip = #{ip}
)s join `doh_attribute` da on da.ip = s.ip JOIN `ip_information` ii ON s.ip = ii.ip
da.`port` = #{params.port}
GROUP BY ii.province having ii.province IS NOT NULL AND ii.province !=''

SELECT ii.`provider`,COUNT(distinct s.ip) COUNT FROM ( select sc.id,sc.ip from `scan_result` sc
sc.ip = #{ip}
)s join `doh_attribute` da on da.ip = s.ip JOIN `ip_information` ii ON s.ip = ii.ip
da.`port` = #{params.port}
GROUP BY ii.provider having ii.provider IS NOT NULL AND ii.provider !=''

SELECT
da.component component,count(distinct da.ip) count
FROM ( select count(1),d.ip,d.component from doh_attribute d
where d.component IS NOT NULL AND d.component !=''

   AND d.ip = #{ip}

) da
JOIN scan_result s on da.ip = s.ip


        da.`port` = #{params.port}


GROUP BY da.component
having da.component IS NOT NULL AND da.component !=''

SELECT count(DISTINCT da.ip)
from (select count(1),d.ip from doh_attribute d


        d.ip = #{params.ip}


        and d.`port` = #{params.port}


group by d.ip) da
join scan_result sc on da.ip = sc.ip

SELECT vulnerability, COUNT(distinct ip) count FROM ( select da.ip, dv.vulnerability from (select count(1), d.ip, d.component from doh_attribute d where d.component is not null and d.component != ''
and d.ip = #{params.ip}
and d.`port` = #{params.port}
group by d.ip, d.component) da join scan_result sc on da.ip = sc.ip join (select distinct v.vulnerability, d.component, d.ip from doh_attribute d JOIN `vulnerability` v ON v.`component` = d.`component`) dv on da.ip = dv.ip where dv.vulnerability is not null and dv.vulnerability != ''
union all
select s.ip, dv.vulnerability from (select count(1), d.ip from doh_attribute d group by d.ip ) da join scan_result s on da.ip = s.ip join (select distinct v.vulnerability, sc.component, sc.ip from scan_result sc JOIN `vulnerability` v ON v.`component` = sc.`component`) dv on s.ip = dv.ip where dv.vulnerability is not null and dv.vulnerability != ''
and s.ip = #{params.ip}
) a1 GROUP BY a1.vulnerability
